import logging

from taf.config.testline import TestLine

from ta_logcollector.utils.mainwindow_utils import check_tl_config_for_ue_sim


def _update_config_for_ue_sim(lc_config: dict, taf_tl_config: TestLine, logger: logging.Logger) -> None:
    # TODO unblock airphone when plugin done.
    # lc_config['ue_sim']['airphone']['active'] = False  # Block airphone until it's not done.
    for simulator in ["cus", "iphy"]:
        sim_exists = any(type(ue).__name__.lower() == simulator for ue in taf_tl_config.ues)
        logger.debug(f"simulator {simulator} exists = {sim_exists}")
        lc_config["ue_sim"][simulator]["active"] &= sim_exists


def _update_config_for_emss(lc_config: dict, taf_tl_config: TestLine, logger: logging.Logger) -> None:
    bts_count = len(taf_tl_config.enbs or []) + len(taf_tl_config.gnbs or [])
    for bts_id in filter(lambda x: x.startswith("bts_"), lc_config["emss"]):
        bts_exists = True if int(bts_id.split("_")[-1]) <= bts_count else False
        logger.debug(f"BTS {bts_id} exists = {bts_exists}")
        lc_config["emss"][bts_id] &= bts_exists


def _update_config_for_final_report(lc_config: dict, taf_tl_config: TestLine) -> None:
    if lc_config["final_report"]["ue_sim_sw"]:
        lc_config["final_report"]["ue_sim_sw"] = {
            sim: sim_exists for sim, sim_exists in check_tl_config_for_ue_sim(taf_tl_config) if sim_exists
        }


def update_config_for_plugins(lc_config: dict, taf_tl_config: TestLine, logger: logging.Logger) -> None:
    _update_config_for_ue_sim(lc_config, taf_tl_config, logger)
    _update_config_for_emss(lc_config, taf_tl_config, logger)
    _update_config_for_final_report(lc_config, taf_tl_config)
